#include <cstddef>
#include <cstdint>

bool parse_uint(const char* text, std::size_t length, std::uint32_t& out);

auto parse_uint(const char* text, std::size_t length, std::uint32_t& out) -> bool {
    if (length == 0) {
        return false;
    }

    std::uint64_t value = 0;
    for (std::size_t i = 0; i < length; ++i) {
        char digit = text[i];
        if (digit < '0' || digit > '9') {
            return false;
        }
        value = value * 10 + static_cast<std::uint64_t>(digit - '0');
        if (value > 0xFFFF'FFFFull) {
            return false;
        }
    }

    out = static_cast<std::uint32_t>(value);
    return true;
}

#include <cstdint>

std::uint64_t next_frame_id();
void send(std::uint64_t first, std::uint64_t second);

void send_pair() {
    // send(next_frame_id(), next_frame_id()) is *unspecified*, not undefined:
    // since C++17 the two argument evaluations are indeterminately sequenced,
    // so one finishes before the other starts -- but the implementation, not
    // the source order, chooses which one runs first.
    std::uint64_t first = next_frame_id();
    std::uint64_t second = next_frame_id();
    send(first, second);
}

