#include <cstddef>

using Classifier = bool (*)(char);

bool is_digit(char c) {
    return c >= '0' && c <= '9';
}

bool is_blank(char c) {
    return c == ' ' || c == '\t';
}

bool is_quote(char c) {
    return c == '"' || c == '\'';
}

constexpr Classifier kClassifiers[] = {is_digit, is_blank, is_quote};
constexpr std::size_t kClassifierCount =
    sizeof(kClassifiers) / sizeof(kClassifiers[0]);

std::size_t classify(char c) {
    for (std::size_t i = 0; i < kClassifierCount; ++i) {
        if (kClassifiers[i](c)) {
            return i;
        }
    }
    return kClassifierCount;
}

