#include <string>

std::string make_label();     // returns a prvalue
std::string& stored_label();  // the call expression is an lvalue

void bind_demo() {
    std::string label = "cursor";

    std::string& alias = label;                      // lvalue
    const std::string& made = make_label();          // prvalue, lifetime extended
    std::string& existing = stored_label();          // lvalue
    const std::string& joined = label + "!";         // prvalue

    // std::string& bad = label + "!";
    // A non-const lvalue reference cannot bind to a prvalue: the addition
    // produces a value with no identity, so there is nothing to alias.

    (void)alias;
    (void)made;
    (void)existing;
    (void)joined;
}
